const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const F = JSON.parse(await fs.readFile(S+"\\_GIG_FINAL_V2.json","utf8"));

// 判断每个平台是否「面向大学生」
const STUDENT_SERVE = ["varsitytutors.com","studypool.com","cambly.com","preply.com","wyzant.com","tutorhunt.com","latinhire.com"];
const STUDENT_USED = ["prolific.com","clickworker.com","scribie.com","gotranscript.com","transcribeme.com","castingwords.com","userfeel.com","userlytics.com","validately.com","usabilityhub.com","userzoom.com","testingtime.com","playtestcloud.com","oneforma.com","tolower","toloka.ai","micron","microworkers.com","prizerebel.com","figure-eight.com","dataannotation.tech","outlier.ai","alignerr.com","mercor.com"];

const all = [];
for (const [cat, items] of Object.entries(F.groups)) for (const it of items) all.push({...it, cat});

const serve = all.filter(a=>STUDENT_SERVE.includes(String(a.host).toLowerCase()));
const used = all.filter(a=>STUDENT_USED.includes(String(a.host).toLowerCase()));
const neutral = all.filter(a=>!serve.includes(a) && !used.includes(a));

return {
  total: all.length,
  serveStudents: serve.length,
  commonlyUsedByStudents: used.length,
  notStudentSpecific: neutral.length,
  serveList: serve.map(a=>a.name+" ("+a.cat+")"),
  neutralSample: neutral.slice(0,15).map(a=>a.name+" ("+a.cat+")")
};
